    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 betLimit, uint256 difficulty) public payable {
        require(address(this).balance >= betLimit);

        // Setup: open contract, set difficulty and bet limit, and wager.
        c.OpenToThePublic();
        c.AdjustDifficulty(difficulty);
        c.AdjustBetAmounts(betLimit);
        c.wager{value: betLimit}();

        // Before play: player must have a wager.
        bool before = c.hasPlayerWagered(address(this));

        // Decide: call play on the current wager.
        bool reverted;
        try c.play() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After play: if it did not revert, the wager must be cleared.
        bool after = c.hasPlayerWagered(address(this));

        assert(before && (reverted || !after));
    }

    receive() external payable {}
}

